     1→/**
     2→ * FreeLang v2 Phase 5 - Minimal AST
     3→ *
     4→ * .free 파일 형식만 지원하는 축소된 AST
     5→ *
     6→ * 예시:
     7→ *   @minimal
     8→ *   fn sum
     9→ *   input: array<number>
    10→ *   output: number
    11→ *   intent: "배열 합산"
    12→ */
    13→
    14→/**
    15→ * Minimal Function AST
    16→ *
    17→ * .free 파일의 함수 선언을 나타내는 최소 구조
    18→ *
    19→ * Phase 5 Tasks:
    20→ *   Task 1-3: 헤더만 (decorator, fnName, types, intent)
    21→ *   Task 4: 본체 지원 (body 필드)
    22→ */
    23→export interface MinimalFunctionAST {
    24→  // 선언 타입
    25→  decorator?: 'minimal'; // @minimal 있으면 'minimal'
    26→
    27→  // 함수 정보
    28→  fnName: string;        // 함수명
    29→  typeParams?: string[]; // 타입 매개변수 (예: ["T", "U"])  - Phase 5 Task 5
    30→  inputType: string;     // 입력 타입 (예: "array<number>")
    31→  outputType: string;    // 출력 타입 (예: "number")
    32→
    33→  // 의도 및 설명
    34→  intent?: string;       // 의도 (예: "배열 합산")
    35→  reason?: string;       // 추가 설명 (선택사항)
    36→
    37→  // Phase 5 Task 4: 함수 본체 (선택사항)
    38→  body?: string;         // 함수 본체 코드 (예: "return arr.reduce(...)")
    39→
    40→  // 원본 정보
    41→  source?: {
    42→    line: number;
    43→    column: number;
    44→  };
    45→}
    46→
    47→/**
    48→ * Parse error
    49→ */
    50→export class ParseError extends Error {
    51→  constructor(
    52→    public line: number,
    53→    public column: number,
    54→    message: string
    55→  ) {
    56→    super(`[${line}:${column}] ${message}`);
    57→    this.name = 'ParseError';
    58→  }
    59→}
    60→
    61→/**
    62→ * Phase 2: Full AST Support
    63→ * Task 2.1-2.3에서 필요한 완전한 AST 타입들
    64→ */
    65→
    66→// 표현식 (Expression)
    67→export type Expression =
    68→  | LiteralExpression
    69→  | IdentifierExpression
    70→  | BinaryOpExpression
    71→  | CallExpression
    72→  | ArrayExpression
    73→  | MemberExpression
    74→  | MatchExpression
    75→  | LambdaExpression
    76→  | AwaitExpression;  // Phase J: await expression
    77→
    78→export interface LiteralExpression {
    79→  type: 'literal';
    80→  value: string | number | boolean;
    81→  dataType: 'number' | 'string' | 'bool';
    82→}
    83→
    84→export interface IdentifierExpression {
    85→  type: 'identifier';
    86→  name: string;
    87→}
    88→
    89→export interface BinaryOpExpression {
    90→  type: 'binary';
    91→  operator: '+' | '-' | '*' | '/' | '%' | '==' | '!=' | '>' | '<' | '>=' | '<=';
    92→  left: Expression;
    93→  right: Expression;
    94→}
    95→
    96→export interface CallExpression {
    97→  type: 'call';
    98→  callee: string;
    99→  arguments: Expression[];
   100→}
   101→
   102→export interface ArrayExpression {
   103→  type: 'array';
   104→  elements: Expression[];
   105→}
   106→
   107→export interface MemberExpression {
   108→  type: 'member';
   109→  object: Expression;
   110→  property: string;
   111→}
   112→
   113→/**
   114→ * Phase 3 Step 3: Lambda Expression (Functions & Closures)
   115→ * Supports anonymous functions with parameter types and closure capture
   116→ */
   117→export interface LambdaExpression {
   118→  type: 'lambda';
   119→  params: Parameter[];        // Parameter definitions
   120→  paramTypes?: string[];      // Optional type annotations for params
   121→  body: Expression;           // Lambda body expression
   122→  returnType?: string;        // Optional return type annotation
   123→  capturedVars?: string[];    // Variables captured from enclosing scope
   124→}
   125→
   126→/**
   127→ * Phase J: Await Expression
   128→ * Pauses execution until a Promise resolves
   129→ * Only valid inside async functions
   130→ */
   131→export interface AwaitExpression {
   132→  type: 'await';
   133→  argument: Expression;  // Expression that returns a Promise<T>
   134→}
   135→
   136→/**
   137→ * Phase 4 Step 1: Module System - Import/Export Support
   138→ * Enables multi-file projects with type-safe imports and exports
   139→ */
   140→
   141→// Import specifier (what to import)
   142→export interface ImportSpecifier {
   143→  name: string;               // Original export name in source module
   144→  alias?: string;             // Renamed as (optional)
   145→}
   146→
   147→// Import statement
   148→export interface ImportStatement {
   149→  type: 'import';
   150→  imports: ImportSpecifier[];  // Named imports

