   450→export interface ForOfStatement {
   451→  type: 'forOf';  // Distinguish from 'for' (range-based)
   452→  variable: string;
   453→  variableType?: string;  // Phase 2: Optional type annotation
   454→  iterable: Expression;
   455→  body: BlockStatement;
   456→  isLet?: boolean;  // Track if 'let' keyword was used
   457→}
   458→
   459→export interface WhileStatement {
   460→  type: 'while';
   461→  condition: Expression;
   462→  body: BlockStatement;
   463→}
   464→
   465→export interface ReturnStatement {
   466→  type: 'return';
   467→  argument?: Expression;
   468→}
   469→
   470→export interface BlockStatement {
   471→  type: 'block';
   472→  body: Statement[];
   473→}
   474→
   475→// Phase I: Exception Handling - Try Statement
   476→export interface TryStatement {
   477→  type: 'try';
   478→  body: BlockStatement;           // try block
   479→  catchClauses?: CatchClause[];   // catch blocks (optional, can be multiple)
   480→  finallyBody?: BlockStatement;   // finally block (optional)
   481→}
   482→
   483→// Phase I: Catch Clause
   484→export interface CatchClause {
   485→  parameter?: string;  // Error variable name (e.g., "err" in catch(err))
   486→  body: BlockStatement;  // catch block body
   487→}
   488→
   489→// Phase I: Throw Statement
   490→export interface ThrowStatement {
   491→  type: 'throw';
   492→  argument: Expression;  // Expression to throw (usually string)
   493→}
   494→
   495→// 함수 (FunctionStatement)
   496→export interface FunctionStatement {
   497→  type: 'function';
   498→  name: string;
   499→  typeParams?: string[];  // Type parameters (e.g., ["T", "U"]) - Phase 5 Task 5
   500→  params: Parameter[];
   501→  returnType?: string;
   502→  body: BlockStatement;
   503→  intent?: string;
   504→  async?: boolean;  // Phase J: async function flag
   505→  source?: {
   506→    line: number;
   507→    column: number;
   508→  };
   509→}
   510→
