   540→}
   541→
   542→export interface UnionTypeObject {
   543→  kind: 'union';
   544→  members: TypeAnnotationObject[];
   545→}
   546→
   547→export interface GenericTypeRef {
   548→  kind: 'generic';
   549→  name: string;
   550→  typeArguments: TypeAnnotationObject[];
   551→}
   552→
   553→export interface ArrayTypeRef {
   554→  kind: 'array';
   555→  element: TypeAnnotationObject;
   556→}
   557→
   558→export interface FunctionTypeRef {
   559→  kind: 'function';
   560→  paramTypes: TypeAnnotationObject[];
   561→  returnType: TypeAnnotationObject;
   562→}
