    97→  private inferStackTypes(count: number): string[] {
    98→    const types: string[] = [];
    99→    const startIdx = Math.max(0, this.stack.length - count);
   100→    for (let i = startIdx; i < this.stack.length; i++) {
   101→      types.push(this.inferType(this.stack[i]));
