   109→  private checkTypeCompatibility(funcName: string, argTypes: string[], expectedParams: Record<string, string>, paramNames: string[]): boolean {
   110→    const result = this.typeChecker.checkFunctionCall(
   111→      funcName,
   112→      argTypes,
   113→      expectedParams,
   114→      paramNames
   115→    );
   116→
   117→    if (!result.compatible) {
   118→      this.typeWarnings.push({
   119→        functionName: funcName,
