   121→        timestamp: new Date(),
   122→        paramName: result.details?.paramName,
   123→        expectedType: result.details?.expected,
   124→        receivedType: result.details?.received
   125→      });
   126→      console.warn(`Type warning in '${funcName}': ${result.message}`);
