   153→  run(program: Inst[]): VMResult {
   154→    this.stack = [];
   155→    this.vars = new Map();
   156→    this.pc = 0;
   157→    this.cycles = 0;
   158→    this.callStack = [];
   159→    this.tryStack = [];  // Phase I: Reset exception stack
   160→    const t0 = performance.now();
   161→
   162→    try {
   163→      // Performance optimization: hot path execution
   164→      while (this.pc < program.length) {
   165→        if (this.cycles++ > MAX_CYCLES) {
   166→          return this.fail(program[this.pc]?.op ?? Op.HALT, 1, 'cycle_limit');
   167→        }
   168→        const inst = program[this.pc];
   169→
   170→        // Hot path: handle most common operations directly
   171→        if (this.hotPathOps.has(inst.op)) {
   172→          this.execHotPath(inst, program);
   173→        } else {
   174→          this.exec(inst, program);
   175→        }
   176→
   177→        if (inst.op === Op.HALT) break;
   178→      }
   179→
   180→      const value = this.stack.length > 0 ? this.stack[this.stack.length - 1] : undefined;
   181→      return { ok: true, value, cycles: this.cycles, ms: performance.now() - t0 };
   182→    } catch (e: unknown) {
   183→      const msg = e instanceof Error ? e.message : String(e);
   184→      return this.fail(program[this.pc]?.op ?? Op.HALT, 99, msg, performance.now() - t0);
   185→    }
   186→  }
   187→
   188→  /**
   189→   * Hot path execution for most common operations
   190→   * Performance optimization (Phase C): Avoid switch dispatch overhead
   191→   */
   192→  private execHotPath(inst: Inst, program: Inst[]): void {
   193→    const op = inst.op;
   194→
   195→    // PUSH: most common operation
   196→    if (op === Op.PUSH) {
   197→      this.guardStack();
   198→      this.stack.push(inst.arg as number);
   199→      this.pc++;
   200→      return;
   201→    }
   202→
   203→    // POP
   204→    if (op === Op.POP) {
   205→      this.need(1);
   206→      this.stack.pop();
   207→      this.pc++;
   208→      return;
   209→    }
   210→
   211→    // Binary arithmetic (hot operations in math-heavy code)
   212→    if (op === Op.ADD) {
   213→      this.binop((a, b) => a + b);
   214→      return;
   215→    }
   216→    if (op === Op.SUB) {
   217→      this.binop((a, b) => a - b);
   218→      return;
   219→    }
   220→    if (op === Op.MUL) {
   221→      this.binop((a, b) => a * b);
   222→      return;
   223→    }
   224→    if (op === Op.DIV) {
   225→      this.need(2);
   226→      if (this.stack[this.stack.length - 1] === 0) {
   227→        throw new Error('div_zero');
   228→      }
   229→      this.binop((a, b) => a / b);
   230→      return;
   231→    }
   232→
   233→    // LOAD: common variable access
   234→    if (op === Op.LOAD) {
   235→      const varName = inst.arg as string;
   236→      const v = this.vars.get(varName);
   237→      if (process.env.DEBUG_STORE) {
   238→        console.log(`[DEBUG LOAD] Getting vars["${varName}"]`);
   239→        console.log(`[DEBUG LOAD] vars keys available:`, Array.from(this.vars.keys()));
   240→        console.log(`[DEBUG LOAD] Result:`, v);
   241→      }
   242→      if (v === undefined) throw new Error('undef_var:' + varName);
   243→      this.guardStack();
   244→      this.stack.push(v);
   245→      this.pc++;
   246→      return;
   247→    }
   248→
   249→    // STORE: common variable assignment
   250→    if (op === Op.STORE) {
   251→      this.need(1);
   252→      const varName = inst.arg as string;
   253→      const value = this.stack.pop()!;
   254→      if (process.env.DEBUG_STORE) {
   255→        console.log(`[DEBUG STORE] Setting vars["${varName}"] = ${JSON.stringify(value)}`);
   256→        console.log(`[DEBUG STORE] vars keys before:`, Array.from(this.vars.keys()));
   257→      }
   258→      this.vars.set(varName, value);
   259→      if (process.env.DEBUG_STORE) {
   260→        console.log(`[DEBUG STORE] vars keys after:`, Array.from(this.vars.keys()));
   261→        console.log(`[DEBUG STORE] vars["${varName}"] =`, this.vars.get(varName));
   262→      }
   263→      this.pc++;
   264→      return;
   265→    }
   266→
   267→    // Fallback to main exec for other hot path ops
   268→    this.exec(inst, program);
   269→  }
   270→
   271→  private exec(inst: Inst, program: Inst[]): void {
   272→    const { op, arg } = inst;
   273→
   274→    switch (op) {
   275→      // ── Stack ──
   276→      case Op.PUSH:
   277→        this.guardStack();
   278→        this.stack.push(arg as number);
   279→        this.pc++;
   280→        break;
   281→
   282→      case Op.PUSH_FLOAT:
   283→        this.guardStack();
   284→        this.stack.push(arg as number);  // JavaScript number is 64-bit float
   285→        this.pc++;
   286→        break;
   287→
   288→      case Op.POP:
   289→        this.need(1);
   290→        this.stack.pop();
   291→        this.pc++;
   292→        break;
   293→
   294→      case Op.DUP:
   295→        this.need(1);
   296→        this.guardStack();
   297→        this.stack.push(this.stack[this.stack.length - 1]);
   298→        this.pc++;
   299→        break;
   300→
   301→      // ── Arithmetic ──
   302→      case Op.ADD: this.binop((a, b) => a + b); break;
   303→      case Op.SUB: this.binop((a, b) => a - b); break;
   304→      case Op.MUL: this.binop((a, b) => a * b); break;
   305→      case Op.DIV:
   306→        this.need(2);
   307→        if (this.stack[this.stack.length - 1] === 0) {
   308→          throw new Error('div_zero');
   309→        }
   310→        this.binop((a, b) => a / b);
   311→        break;
   312→      case Op.MOD: this.binop((a, b) => a % b); break;
   313→      case Op.NEG:
   314→        this.need(1);
   315→        this.stack[this.stack.length - 1] = -this.stack[this.stack.length - 1];
   316→        this.pc++;
   317→        break;
   318→
   319→      // ── Float Arithmetic (Phase 3 Level 3) ──
   320→      case Op.FADD: this.binop((a, b) => a + b); break;  // Same as ADD (JavaScript number is f64)
   321→      case Op.FSUB: this.binop((a, b) => a - b); break;
   322→      case Op.FMUL: this.binop((a, b) => a * b); break;
   323→      case Op.FDIV:
   324→        this.need(2);
   325→        if (this.stack[this.stack.length - 1] === 0) {
   326→          throw new Error('fdiv_zero');
   327→        }
   328→        this.binop((a, b) => a / b);
   329→        break;
   330→
   331→      // ── Float Conversions ──
   332→      case Op.F2I:  // float → int
   333→        this.need(1);
   334→        this.stack[this.stack.length - 1] = Math.trunc(this.stack[this.stack.length - 1] as number);
   335→        this.pc++;
   336→        break;
   337→      case Op.I2F:  // int → float (no-op in JavaScript, but semantically correct)
   338→        this.need(1);
   339→        this.stack[this.stack.length - 1] = Number(this.stack[this.stack.length - 1] as number);
   340→        this.pc++;
   341→        break;
   342→
   343→      // ── Comparison ──
   344→      case Op.EQ:  this.binop((a, b) => a === b ? 1 : 0); break;
   345→      case Op.NEQ: this.binop((a, b) => a !== b ? 1 : 0); break;
   346→      case Op.LT:  this.binop((a, b) => a < b ? 1 : 0); break;
   347→      case Op.GT:  this.binop((a, b) => a > b ? 1 : 0); break;
   348→      case Op.LTE: this.binop((a, b) => a <= b ? 1 : 0); break;
   349→      case Op.GTE: this.binop((a, b) => a >= b ? 1 : 0); break;
   350→
   351→      // ── Logic ──
   352→      case Op.AND: this.binop((a, b) => (a && b) ? 1 : 0); break;
   353→      case Op.OR:  this.binop((a, b) => (a || b) ? 1 : 0); break;
   354→      case Op.NOT:
   355→        this.need(1);
   356→        this.stack[this.stack.length - 1] = this.stack[this.stack.length - 1] ? 0 : 1;
   357→        this.pc++;
   358→        break;
   359→
   360→      // ── Variables ──
   361→      case Op.STORE:
   362→        this.need(1);
   363→        this.vars.set(arg as string, this.stack.pop()!);
   364→        this.pc++;
   365→        break;
   366→
   367→      case Op.LOAD: {
   368→        const v = this.vars.get(arg as string);
   369→        if (v === undefined) throw new Error('undef_var:' + arg);
   370→        // Push any value type to stack (number, string, array, object)
   371→        this.guardStack();
   372→        this.stack.push(v);
   373→        this.pc++;
   374→        break;
   375→      }
   376→
   377→      // ── Control ──
   378→      case Op.JMP:
   379→        this.pc = arg as number;
   380→        break;
   381→
   382→      case Op.JMP_IF:
   383→        this.need(1);
   384→        this.pc = this.stack.pop()! ? (arg as number) : this.pc + 1;
   385→        break;
   386→
   387→      case Op.JMP_NOT:
   388→        this.need(1);
   389→        this.pc = this.stack.pop()! ? this.pc + 1 : (arg as number);
   390→        break;
   391→
   392→      case Op.RET:
   393→      case Op.HALT:
   394→        this.pc = program.length; // exit
   395→        break;
   396→
   397→      // ── Array ──
   398→      case Op.ARR_NEW:
   399→        this.vars.set(arg as string, []);
   400→        this.pc++;
   401→        break;
   402→
   403→      case Op.ARR_PUSH: {
   404→        this.need(1);
   405→        const arr = this.vars.get(arg as string);
   406→        if (!Array.isArray(arr)) throw new Error('not_array:' + arg);
   407→        arr.push(this.stack.pop() as number);
   408→        this.pc++;
   409→        break;
   410→      }
   411→
   412→      case Op.ARR_GET: {
   413→        this.need(2);
   414→        // If arg is provided, use variable-based access
   415→        // Otherwise use stack-based access: stack = [... array/object, index/key]
   416→        let container;
   417→        let key;
   418→
   419→        if (arg) {
   420→          // Variable-based: container = vars[arg], key = stack.pop()
   421→          container = this.vars.get(arg as string);
   422→          if (!container || (typeof container !== 'object')) throw new Error('not_indexable:' + arg);
   423→          key = this.stack.pop();
   424→        } else {
   425→          // Stack-based: pop key, then pop container (array or object)
   426→          key = this.stack.pop();
   427→          container = this.stack.pop();
   428→          if (!container || typeof container !== 'object') throw new Error('not_indexable:stack');
   429→        }
   430→
   431→        // Handle both arrays and objects
   432→        let value;
   433→        if (Array.isArray(container)) {
   434→          // Convert float indices to int (truncate)
   435→          const idx = Math.floor(key as number);
   436→          if (idx < 0 || idx >= container.length) throw new Error('oob:' + idx);
   437→          value = container[idx];
   438→        } else {
   439→          // Object: use string key
   440→          const strKey = String(key);
   441→          value = (container as any)[strKey];
   442→        }
   443→
   444→        this.guardStack();
   445→        this.stack.push(value);
   446→        this.pc++;
   447→        break;
   448→      }
   449→
   450→      case Op.ARR_SET: {
   451→        this.need(2);
   452→        const container = this.vars.get(arg as string);
   453→        if (!container || typeof container !== 'object') throw new Error('not_indexable:' + arg);
   454→        const val = this.stack.pop();
   455→        const key = this.stack.pop();
   456→
   457→        // Handle both arrays and objects
   458→        if (Array.isArray(container)) {
   459→          // Convert float indices to int (truncate)
   460→          const idx = Math.floor(key as number);
   461→          if (idx < 0 || idx >= container.length) throw new Error('oob:' + idx);
   462→          container[idx] = val;
   463→        } else {
   464→          // Object: use string key
   465→          const strKey = String(key);
   466→          (container as any)[strKey] = val;
   467→        }
   468→
   469→        this.pc++;
   470→        break;
   471→      }
   472→
   473→      case Op.ARR_LEN: {
   474→        let value;
   475→        if (arg) {
   476→          // Variable-based: value = this.vars.get(arg)
   477→          value = this.vars.get(arg as string);
   478→        } else {
   479→          // Stack-based: pop value from stack
   480→          this.need(1);
   481→          value = this.stack.pop();
   482→        }
   483→
   484→        // Support both arrays and strings
   485→        if (value === null || value === undefined) {
   486→          throw new Error('length_on_null');
   487→        }
   488→
   489→        // Get length property - works for arrays and strings
   490→        const len = (value as any).length;
   491→        if (typeof len !== 'number') {
   492→          throw new Error('no_length_property');
   493→        }
   494→
   495→        this.guardStack();
   496→        this.stack.push(len);
   497→        this.pc++;
   498→        break;
   499→      }
   500→
   501→      // ── Object Operations ──────────────────
   502→      case Op.OBJ_NEW:
   503→        this.vars.set(arg as string, {});
   504→        this.pc++;
   505→        break;
   506→
   507→      case Op.OBJ_SET: {
   508→        this.need(1);
   509→        const argStr = arg as string;
   510→        const colonIdx = argStr.indexOf(':');
   511→        if (colonIdx === -1) throw new Error('invalid_obj_set:' + argStr);
   512→        const varName = argStr.substring(0, colonIdx);
   513→        const key = argStr.substring(colonIdx + 1);
   514→        const obj = this.vars.get(varName);
   515→        if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
   516→          throw new Error('not_object:' + varName);
   517→        }
   518→        const val = this.stack.pop();
   519→        (obj as any)[key] = val;
   520→        this.pc++;
   521→        break;
   522→      }
   523→
   524→      case Op.OBJ_GET: {
   525→        this.need(2);
   526→        const key = this.stack.pop() as string;
   527→        const obj = this.stack.pop();
   528→        if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
   529→          throw new Error('not_object:stack');
   530→        }
   531→        this.guardStack();
   532→        const result = (obj as any)[key];
   533→        this.stack.push(result !== undefined ? result : null);
   534→        this.pc++;
   535→        break;
   536→      }
   537→
   538→      // ── Array Aggregate (AI shorthand) ──
   539→      case Op.ARR_SUM: {
   540→        const arr = this.getArr(arg as string);
   541→        this.guardStack();
   542→        this.stack.push(arr.reduce((s, x) => s + x, 0));
   543→        this.pc++;
   544→        break;
   545→      }
   546→
   547→      case Op.ARR_AVG: {
   548→        const arr = this.getArr(arg as string);
   549→        if (arr.length === 0) throw new Error('empty_arr_avg');
   550→        this.guardStack();
   551→        this.stack.push(arr.reduce((s, x) => s + x, 0) / arr.length);
   552→        this.pc++;
   553→        break;
   554→      }
   555→
   556→      case Op.ARR_MAX: {
   557→        const arr = this.getArr(arg as string);
   558→        if (arr.length === 0) throw new Error('empty_arr_max');
   559→        this.guardStack();
   560→        this.stack.push(Math.max(...arr));
   561→        this.pc++;
   562→        break;
   563→      }
   564→
   565→      case Op.ARR_MIN: {
   566→        const arr = this.getArr(arg as string);
   567→        if (arr.length === 0) throw new Error('empty_arr_min');
   568→        this.guardStack();
   569→        this.stack.push(Math.min(...arr));
   570→        this.pc++;
   571→        break;
   572→      }
   573→
   574→      case Op.ARR_SORT: {
   575→        const arr = this.getArr(arg as string);
   576→        arr.sort((a, b) => a - b);
   577→        this.pc++;
   578→        break;
   579→      }
   580→
   581→      case Op.ARR_REV: {
   582→        const arr = this.getArr(arg as string);
   583→        arr.reverse();
   584→        this.pc++;
   585→        break;
   586→      }
   587→
   588→      case Op.ARR_MAP: {
   589→        const arr = this.getArr(arg as string);
   590→        if (!inst.sub) throw new Error('arr_map_no_sub');
   591→        const result: number[] = [];
   592→        for (const elem of arr) {
   593→          const savedStack = this.stack;
   594→          this.stack = [elem];
   595→          this.runSub(inst.sub);
   596→          const mappedVal = (this.stack.length > 0 ? this.stack[0] : 0) as number;
   597→          result.push(mappedVal);
   598→          this.stack = savedStack;
   599→        }
   600→        this.vars.set(arg as string, result);
   601→        this.pc++;
   602→        break;
   603→      }
   604→
   605→      case Op.ARR_FILTER: {
   606→        const arr = this.getArr(arg as string);
   607→        if (!inst.sub) throw new Error('arr_filter_no_sub');
   608→        const result: number[] = [];
   609→        for (const elem of arr) {
   610→          const savedStack = this.stack;
   611→          this.stack = [elem];
   612→          this.runSub(inst.sub);
   613→          const cond = this.stack.length > 0 ? this.stack[0] : 0;
   614→          if (cond) result.push(elem);
   615→          this.stack = savedStack;
   616→        }
   617→        this.vars.set(arg as string, result);
   618→        this.pc++;
   619→        break;
   620→      }
   621→
   622→      case Op.CALL: {
   623→        // Phase 19: Support both user-defined functions and legacy sub-programs
   624→        // Phase 21: Add type checking and validation
   625→        // Phase 3 FFI: Support native functions (C FFI)
   626→        // Phase J: Support async functions
   627→        const funcName = inst.arg as string;
   628→
   629→        // Try user-defined function first
   630→        if (this.functionRegistry && funcName && this.functionRegistry.exists(funcName)) {
   631→          const fn = this.functionRegistry.lookup(funcName);
