     8→  HALT = 1,
     9→  MOV = 2,
    10→  ADD = 3,
    11→  SUB = 4,
    12→  MUL = 5,
    13→  DIV = 6,
    14→  CMP = 7,
    15→  JMP = 8,
    16→  JMP_IF = 9,
    17→  CALL = 10,
    18→  RET = 11,
    19→  PUSH = 12,
    20→  POP = 13,
    21→  LOAD = 14,
    22→  STORE = 15,
    23→  TRY_BEGIN = 16,
    24→  TRY_END = 17,
    25→  RAISE = 18,
    26→  CATCH = 19,
    27→  FOR_INIT = 20,
    28→  FOR_NEXT = 21,
    29→}
    30→
    31→/**
    32→ * FreeLang VM
    33→ */
    34→export class VM {
    35→  // 레지스터 (8개, 각 32비트)
    36→  private registers: number[] = new Array(8).fill(0);
    37→
    38→  // 메모리 (4KB)
    39→  private memory: number[] = new Array(4096).fill(0);
    40→
    41→  // 스택 (1K 엔트리)
    42→  private stack: number[] = [];
    43→
    44→  // 프로그램 카운터
    45→  private pc: number = 0;
    46→
    47→  // 플래그
    48→  private flags = {
    49→    Z: false, // Zero
    50→    C: false, // Carry
    51→    S: false, // Sign
    52→    E: false, // Equal
    53→    L: false, // Less
    54→  };
