    ctx.stack.push(value?.tag === 'none');
    ctx.pc++;
  };

  private handleUnwrap = (ctx: DispatcherContext): void => {
    ctx.need(1);
    const value = ctx.stack.pop();
    if (value?.tag === 'ok' || value?.tag === 'some') {
