      const wss = wsServer.wss;
      const server = wsServer.server;

      wss.on('connection', (ws: any) => {
        const client = {
          __type: 'WebSocketConnection',
          id: Math.random().toString(36).substr(2, 9),
          ws: ws,
          state: 1, // OPEN
          username: null
        };

        wsServer.clients.add(client);

