  registry.register({
    name: 'tokenize',
    module: 'lexer',
    executor: (args) => {
      const source = args[0] as string;
      const lexer = {
        source,
        pos: 0,
        line: 1,
        col: 1,
        tokens: [] as any[]
      };

      function current(): string {
        if (lexer.pos >= lexer.source.length) return '';
        return lexer.source[lexer.pos];
      }

      function peek(offset: number): string {
        const pos = lexer.pos + offset;
        if (pos >= lexer.source.length) return '';
        return lexer.source[pos];
      }

      function isAlpha(ch: string): boolean {
        const code = ch.charCodeAt(0);
        return (code >= 97 && code <= 122) || (code >= 65 && code <= 90) || ch === '_';
      }

      function isDigit(ch: string): boolean {
        const code = ch.charCodeAt(0);
        return code >= 48 && code <= 57;
      }

      function isAlphaNumeric(ch: string): boolean {
        return isAlpha(ch) || isDigit(ch);
      }

      function isWhitespace(ch: string): boolean {
        return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r';
      }

      function isOperator(ch: string): boolean {
        return '+-*/%=!<>&|^'.includes(ch);
      }

      function isKeyword(word: string): boolean {
        const keywords = ['fn', 'let', 'const', 'return', 'if', 'else', 'while', 'for',
          'do', 'break', 'continue', 'match', 'true', 'false', 'null', 'struct', 'enum',
          'import', 'export', 'async', 'await', 'try', 'catch', 'finally', 'throw', 'in', 'of'];
        return keywords.includes(word);
      }

      function addToken(kind: string, value: string, line: number, col: number): void {
        lexer.tokens.push({
          kind,
          value,
          line,
          col,
          length: value.length
        });
      }

      function scanNumber(): void {
        const start = lexer.pos;
        const line = lexer.line;
        const col = lexer.col;

        while (isDigit(current())) {
          lexer.pos++;
          lexer.col++;
        }

        if (current() === '.' && isDigit(peek(1))) {
          lexer.pos++;
          lexer.col++;
          while (isDigit(current())) {
            lexer.pos++;
            lexer.col++;
          }
        }

        const value = lexer.source.substring(start, lexer.pos);
        addToken('NUMBER', value, line, col);
      }

      function scanIdentifier(): void {
        const start = lexer.pos;
        const line = lexer.line;
        const col = lexer.col;

        while (isAlphaNumeric(current())) {
          lexer.pos++;
          lexer.col++;
        }

        const value = lexer.source.substring(start, lexer.pos);
        const kind = isKeyword(value) ? 'KEYWORD' : 'IDENT';
        addToken(kind, value, line, col);
      }

      function scanString(quote: string): void {
        const start = lexer.pos;
        const line = lexer.line;
        const col = lexer.col;

        lexer.pos++;
        lexer.col++;

        while (current() !== quote && current() !== '') {
          if (current() === '\n') {
            lexer.line++;
            lexer.col = 1;
          } else {
            lexer.col++;
          }

          if (current() === '\\' && peek(1) === quote) {
            lexer.pos += 2;
            lexer.col += 2;
          } else {
            lexer.pos++;
          }
        }

        if (current() === quote) {
          lexer.pos++;
          lexer.col++;
        }

        const value = lexer.source.substring(start, lexer.pos);
        addToken('STRING', value, line, col);
      }

      function scanLineComment(): void {
        const start = lexer.pos;
        const line = lexer.line;
        const col = lexer.col;

        lexer.pos += 2;
        lexer.col += 2;

        while (current() !== '\n' && current() !== '') {
          lexer.pos++;
          lexer.col++;
        }

        const value = lexer.source.substring(start, lexer.pos);
        addToken('COMMENT', value, line, col);
      }

      function scanBlockComment(): void {
        const start = lexer.pos;
        const line = lexer.line;
        const col = lexer.col;

        lexer.pos += 2;
        lexer.col += 2;

        while (lexer.pos < lexer.source.length - 1) {
          if (current() === '*' && peek(1) === '/') {
            lexer.pos += 2;
            lexer.col += 2;
            break;
          }

          if (current() === '\n') {
            lexer.line++;
            lexer.col = 1;
          } else {
            lexer.col++;
          }

          lexer.pos++;
        }

        const value = lexer.source.substring(start, lexer.pos);
        addToken('COMMENT', value, line, col);
      }

      function scanOperator(ch: string): void {
        const line = lexer.line;
        const col = lexer.col;
        let value = ch;

        lexer.pos++;
        lexer.col++;

        const next = current();

        if ((ch === '=' && next === '=') ||
            (ch === '!' && next === '=') ||
            (ch === '<' && next === '=') ||
            (ch === '>' && next === '=') ||
            (ch === '&' && next === '&') ||
            (ch === '|' && next === '|') ||
            (ch === '+' && next === '+') ||
            (ch === '-' && next === '-') ||
            (ch === '+' && next === '=') ||
            (ch === '-' && next === '=') ||
            (ch === '*' && next === '=') ||
            (ch === '/' && next === '=')) {
          value += next;
          lexer.pos++;
          lexer.col++;

          if (ch === '=' && next === '=' && current() === '=') {
            value += '=';
            lexer.pos++;
            lexer.col++;
          }
        }

        addToken('OP', value, line, col);
      }

      function nextToken(): void {
        while (isWhitespace(current())) {
          if (current() === '\n') {
            lexer.line++;
            lexer.col = 1;
          } else {
            lexer.col++;
          }
          lexer.pos++;
        }

        const ch = current();

        if (ch === '') {
          return;
        }

        if (ch === '/' && peek(1) === '/') {
          scanLineComment();
          return;
        }

        if (ch === '/' && peek(1) === '*') {
          scanBlockComment();
          return;
        }

        if (isDigit(ch)) {
          scanNumber();
          return;
        }

        if (isAlpha(ch)) {
          scanIdentifier();
          return;
        }

        if (ch === '"' || ch === "'") {
          scanString(ch);
          return;
        }

        if (isOperator(ch)) {
          scanOperator(ch);
          return;
        }

        const line = lexer.line;
        const col = lexer.col;
        lexer.pos++;
        lexer.col++;

        if ('(){}[];:,.?'.includes(ch)) {
          addToken('PUNCT', ch, line, col);
        } else {
          addToken('UNKNOWN', ch, line, col);
        }
      }

      while (lexer.pos < lexer.source.length) {
        nextToken();
      }

      addToken('EOF', '', lexer.line, lexer.col);

      return lexer.tokens;
    }
  });

