   102→  }
   103→
   104→  /**
   105→   * Phase 4 Step 5: Module IR 생성
   106→   *
   107→   * 모듈 전체를 IR로 변환:
   108→   * 1. Import 심볼 바인딩
   109→   * 2. Export 심볼 수집
   110→   * 3. 모듈 본체 IR 생성
   111→   *
   112→   * @param module 파싱된 Module
   113→   * @returns Module IR 지시사항
   114→   */
   115→  public generateModuleIR(module: Module): Inst[] {
   116→    const instructions: Inst[] = [];
   117→
   118→    // Step 1: Import 컨텍스트 구축
   119→    this.moduleLinkContext = {
   120→      importedSymbols: new Map(),
   121→      exportedSymbols: new Map()
   122→    };
   123→
   124→    // Step 2: Import 처리 - 심볼 바인딩
   125→    for (const importStmt of module.imports) {
   126→      this.generateImportIR(importStmt, instructions);
   127→    }
   128→
   129→    // Step 3: Export 심볼 수집
   130→    for (const exportStmt of module.exports) {
   131→      this.collectExportedSymbol(exportStmt);
   132→    }
