// Option<T> 테스트
fn find_first_even(arr) {
  for item in arr {
    if item % 2 == 0 {
      return Some(item);
    }
  }
  return None();
}

let result = find_first_even([1, 3, 4, 5]);
match result {
  Some(v) => print(v),    // 기대: 4
  None => print("not found"),
}

